'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { RefreshCwIcon, RotateCcwIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Skeleton } from '@/registry/ndeko/ui/skeleton';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import { DashboardCard } from './dashboard-card';
import { ACTIVITY, LOAD_DURATION_MS } from './data';
import { fadePresence } from './motion-parts';
import { personOf } from './people';
import { PersonAvatar } from './working-cards';

type LoadState = 'failed' | 'loading' | 'loaded';

const SKELETON_ROWS = ['first', 'second', 'third'];

const META: Record<LoadState, string> = {
  failed: 'Not loaded',
  loading: 'Loading',
  loaded: 'Last 24 hours',
};

function FailedNotice({ onRetry }: { onRetry: () => void }) {
  return (
    <div className='flex items-start gap-3 py-1'>
      <StatusOrb tone='error' size='sm' className='mt-px' />
      <div className='min-w-0 flex-1'>
        <p className='text-[13px] font-medium'>Couldn’t load recent activity</p>
        <p className='text-muted-foreground mt-0.5 text-[13px] text-pretty'>
          The activity service took too long to answer, the other cards are up
          to date
        </p>
        <Button variant='outline' size='sm' onClick={onRetry} className='mt-3'>
          <RotateCcwIcon />
          Retry
        </Button>
      </div>
    </div>
  );
}

function ActivitySkeleton() {
  return (
    <div aria-busy='true' className='flex flex-col gap-3 py-1'>
      <span className='sr-only'>Loading recent activity</span>
      {SKELETON_ROWS.map((row) => (
        <div key={row} className='flex items-center gap-2.5'>
          <Skeleton className='size-6 rounded-full' />
          <Skeleton className='h-2.5 w-2/5' />
          <Skeleton className='ms-auto h-2.5 w-8' />
        </div>
      ))}
    </div>
  );
}

function ActivityList() {
  return (
    <ul className='flex flex-col gap-3 py-1'>
      {ACTIVITY.map((entry) => {
        const person = personOf(entry.personId);
        return (
          <li key={entry.id} className='flex items-center gap-2.5'>
            <PersonAvatar person={person} />
            <p className='text-muted-foreground min-w-0 flex-1 truncate text-[13px]'>
              <span className='text-foreground font-medium'>{person.name}</span>{' '}
              {entry.text}
            </p>
            <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
              {entry.age}
            </span>
          </li>
        );
      })}
    </ul>
  );
}

export function ActivityCard({ className }: { className?: string }) {
  const [state, setState] = useState<LoadState>('failed');
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const isLoaded = state === 'loaded';

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((timer) => clearTimeout(timer));
    };
  }, []);

  function load() {
    setState('loading');
    const timer = setTimeout(() => {
      timers.current.delete(timer);
      setState('loaded');
    }, LOAD_DURATION_MS);
    timers.current.add(timer);
  }

  const reloadButton = (
    <Button
      variant='ghost'
      size='icon-sm'
      aria-label='Reload activity'
      onClick={load}
      className='text-muted-foreground'
    >
      <RefreshCwIcon />
    </Button>
  );

  return (
    <DashboardCard
      title='Recent activity'
      meta={META[state]}
      action={isLoaded && reloadButton}
      className={className}
    >
      <AnimatedSize>
        <div className='relative'>
          <AnimatePresence mode='popLayout' initial={false}>
            <motion.div key={state} {...fadePresence()}>
              {state === 'failed' && <FailedNotice onRetry={load} />}
              {state === 'loading' && <ActivitySkeleton />}
              {isLoaded && <ActivityList />}
            </motion.div>
          </AnimatePresence>
        </div>
      </AnimatedSize>
    </DashboardCard>
  );
}

'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Checkbox } from '@/registry/ndeko/ui/checkbox';

import { DashboardCard } from './dashboard-card';
import { OPEN_TASKS, TEAM, type OpenTask, type Person } from './data';
import { personOf } from './people';

function withDone(tasks: OpenTask[], taskId: string, isDone: boolean) {
  return tasks.map((task) => {
    if (task.id !== taskId) {
      return task;
    }
    return { ...task, isDone };
  });
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar
      className={cn('size-6 text-[10px]', className)}
      seed={person.name}
    />
  );
}

export function OpenTasksCard() {
  const [tasks, setTasks] = useState<OpenTask[]>(OPEN_TASKS);
  const openCount = tasks.filter((task) => !task.isDone).length;

  function toggle(taskId: string, isDone: boolean) {
    setTasks((current) => withDone(current, taskId, isDone));
  }

  return (
    <DashboardCard
      title='Your open tasks'
      meta={
        <span className='inline-flex items-center gap-1 tabular-nums'>
          <MotionNumber value={openCount} /> open
        </span>
      }
    >
      <ul className='-mx-1.5 flex flex-col'>
        {tasks.map((task) => (
          <li key={task.id}>
            <label className='hover:bg-foreground/[0.03] flex h-9 cursor-pointer items-center gap-2.5 rounded-md px-1.5'>
              <Checkbox
                checked={task.isDone}
                onCheckedChange={(checked) => toggle(task.id, checked)}
              />
              <span className='text-muted-foreground w-16 shrink-0 text-xs tabular-nums'>
                {task.key}
              </span>
              <span
                className={cn(
                  'min-w-0 flex-1 truncate text-[13px]',
                  task.isDone && 'text-muted-foreground line-through'
                )}
              >
                {task.title}
              </span>
            </label>
          </li>
        ))}
      </ul>
    </DashboardCard>
  );
}

export function TeamCard() {
  return (
    <DashboardCard title='Team' meta='Working on now'>
      <ul className='flex flex-col gap-3'>
        {TEAM.map((member) => {
          const person = personOf(member.personId);
          return (
            <li key={member.personId} className='flex items-center gap-2.5'>
              <PersonAvatar person={person} />
              <div className='min-w-0 flex-1'>
                <p className='truncate text-[13px]'>{person.name}</p>
                <p className='text-muted-foreground truncate text-xs'>
                  {member.focus ?? 'No task in progress'}
                </p>
              </div>
            </li>
          );
        })}
      </ul>
    </DashboardCard>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

type DashboardCardProps = {
  title: string;
  meta: React.ReactNode;
  action?: React.ReactNode;
  children: React.ReactNode;
  className?: string;
};

export function DashboardCard({
  title,
  meta,
  action,
  children,
  className,
}: DashboardCardProps) {
  return (
    <section
      aria-label={title}
      className={cn(
        'bg-card hairline-ring ring-border flex flex-col rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <div className='flex min-h-7 items-center justify-between gap-2'>
        <div className='flex min-w-0 items-baseline gap-2'>
          <h2 className='truncate text-[13px] font-medium'>{title}</h2>
          <span className='text-muted-foreground shrink-0 text-xs'>{meta}</span>
        </div>
        {action}
      </div>
      <div className='mt-3'>{children}</div>
    </section>
  );
}

import { PEOPLE } from './data';

export function personOf(personId: string) {
  const found = PEOPLE.find((person) => person.id === personId);
  if (found) {
    return found;
  }
  return PEOPLE[0];
}

'use client';

import {
  AnimatePresence,
  motion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

export function fadePresence() {
  return FADE_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={variants}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

